using Microsoft.EntityFrameworkCore;
using WhaleDeck.Domain.Entities;

namespace WhaleDeck.Infrastructure.Persistence;

public sealed partial class PlatformDbContext
{
    private static void ConfigureContainerRecursiveOwnerships(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<ContainerRecursiveOwnershipIntent>(entity =>
        {
            entity.ToTable("container_recursive_ownership_intents", table =>
            {
                table.HasCheckConstraint("ck_container_recursive_ownership_state", "state IN ('Queued','Planning','Ready','Pending','Applying','Unknown','Partial','Succeeded','Superseded','Canceled','Failed','Expired','Acknowledged')");
                table.HasCheckConstraint("ck_container_recursive_ownership_terminal", "(completed_at_utc IS NULL) = (state IN ('Queued','Planning','Ready','Pending','Applying','Unknown','Partial'))");
                table.HasCheckConstraint("ck_container_recursive_ownership_identity", "id <> '00000000-0000-0000-0000-000000000000'::uuid AND idempotency_key <> '00000000-0000-0000-0000-000000000000'::uuid AND container_id ~ '^[a-f0-9]{64}$' AND octet_length(relative_path) BETWEEN 1 AND 4096 AND length(actor_subject) BETWEEN 1 AND 256 AND length(trace_id) BETWEEN 1 AND 128 AND octet_length(command_json) BETWEEN 1 AND 65536");
                table.HasCheckConstraint("ck_container_recursive_ownership_requested_owners", "((jsonb_typeof(command_json::jsonb->'Uid') = 'number' AND command_json::jsonb->>'Uid' ~ '^(0|[1-9][0-9]{0,9})$' AND (command_json::jsonb->>'Uid')::numeric BETWEEN 0 AND 4294967294 AND jsonb_typeof(command_json::jsonb->'Gid') = 'number' AND command_json::jsonb->>'Gid' ~ '^(0|[1-9][0-9]{0,9})$' AND (command_json::jsonb->>'Gid')::numeric BETWEEN 0 AND 4294967294) IS TRUE)");
                table.HasCheckConstraint("ck_container_recursive_ownership_lifetime", "created_at_utc > TIMESTAMPTZ '1970-01-01 00:00:00+00' AND planning_expires_at_utc = created_at_utc + INTERVAL '15 minutes' AND version >= 0");
                table.HasCheckConstraint("ck_container_recursive_ownership_hashes", "login_binding ~ '^[A-F0-9]{64}$' AND owner_hash ~ '^[A-F0-9]{64}$' AND request_hash ~ '^[A-F0-9]{64}$'");
                table.HasCheckConstraint("ck_container_recursive_ownership_plan", "(plan_json IS NULL AND plan_hash IS NULL AND ready_expires_at_utc IS NULL) OR (plan_json IS NOT NULL AND octet_length(plan_json) BETWEEN 1 AND 65536 AND plan_hash IS NOT NULL AND plan_hash ~ '^[A-F0-9]{64}$' AND ready_expires_at_utc IS NOT NULL AND ready_expires_at_utc > created_at_utc AND ready_expires_at_utc <= planning_expires_at_utc + INTERVAL '5 minutes')");
                table.HasCheckConstraint("ck_container_recursive_ownership_execution", "(execution_job_id IS NULL AND confirmed_at_utc IS NULL AND execution_expires_at_utc IS NULL AND execution_hash IS NULL) OR (execution_job_id IS NOT NULL AND execution_job_id <> id AND execution_job_id <> '00000000-0000-0000-0000-000000000000'::uuid AND plan_json IS NOT NULL AND confirmed_at_utc IS NOT NULL AND confirmed_at_utc >= created_at_utc AND confirmed_at_utc < ready_expires_at_utc AND execution_expires_at_utc IS NOT NULL AND execution_expires_at_utc = confirmed_at_utc + INTERVAL '15 minutes' AND execution_hash IS NOT NULL AND execution_hash ~ '^[A-F0-9]{64}$')");
                table.HasCheckConstraint("ck_container_recursive_ownership_phase", "(state NOT IN ('Ready','Pending','Applying','Unknown','Partial','Succeeded','Superseded','Acknowledged') OR plan_json IS NOT NULL) AND (state NOT IN ('Pending','Applying','Unknown','Partial','Succeeded','Superseded','Acknowledged') OR execution_job_id IS NOT NULL) AND (state NOT IN ('Queued','Planning','Ready') OR execution_job_id IS NULL)");
                table.HasCheckConstraint("ck_container_recursive_ownership_barrier", "(NOT publish_barrier OR (completed_at_utc IS NULL AND root_started_at_utc IS NOT NULL AND execution_job_id IS NOT NULL)) AND (root_started_at_utc IS NULL OR execution_job_id IS NOT NULL AND (publish_barrier OR completed_at_utc IS NOT NULL)) AND (state NOT IN ('Applying','Partial') OR publish_barrier)");
                table.HasCheckConstraint("ck_container_recursive_ownership_result", "((state NOT IN ('Succeeded','Superseded') OR root_state = 'Completed' AND history_verified AND root_started_at_utc IS NOT NULL AND binding_current = (state = 'Succeeded')) AND (state <> 'Partial' OR root_state = 'Partial' AND history_verified AND publish_barrier AND root_started_at_utc IS NOT NULL) AND (state <> 'Unknown' OR root_state IS NULL OR root_state = 'Unknown') AND (execution_job_id IS NULL OR state NOT IN ('Canceled','Failed') OR root_state = 'Aborted')) IS TRUE");
                table.HasCheckConstraint("ck_container_recursive_ownership_history", "(NOT history_verified OR history_may_exist AND history_digest IS NOT NULL) AND ((history_digest IS NOT NULL) = history_verified) AND (history_digest IS NULL OR history_digest ~ '^[A-F0-9]{64}$') AND (execution_job_id IS NOT NULL OR root_state IS NULL AND NOT history_may_exist AND NOT history_verified AND history_digest IS NULL) AND (root_started_at_utc IS NOT NULL OR root_state IS NULL OR root_state = 'Aborted')");
                table.HasCheckConstraint("ck_container_recursive_ownership_receipt", "(root_state IS NULL AND receipt_json IS NULL AND completed_count IS NULL AND changed_count IS NULL AND aborted_count IS NULL AND not_started_count IS NULL AND unknown_count IS NULL AND outcome_digest IS NULL AND binding_current IS NULL AND history_available IS NULL) OR ((root_state IN ('Completed','Partial','Aborted','Unknown') AND receipt_json IS NOT NULL AND octet_length(receipt_json) BETWEEN 1 AND 65536 AND execution_job_id IS NOT NULL AND plan_json IS NOT NULL AND completed_count BETWEEN 0 AND 10000 AND changed_count BETWEEN 0 AND completed_count AND aborted_count BETWEEN 0 AND 10000 AND not_started_count BETWEEN 0 AND 10000 AND unknown_count BETWEEN 0 AND 10000 AND binding_current IS NOT NULL AND history_available IS NOT NULL AND outcome_digest IS NOT NULL AND (outcome_digest = '' OR outcome_digest ~ '^[A-F0-9]{64}$') AND completed_count + aborted_count + not_started_count + unknown_count = (plan_json::jsonb->>'EntryCount')::integer AND changed_count <= (plan_json::jsonb->>'ChangeCount')::integer AND (NOT history_available OR history_verified) AND (NOT binding_current OR root_state = 'Completed' AND history_available) AND (root_state <> 'Completed' OR completed_count = (plan_json::jsonb->>'EntryCount')::integer AND changed_count = (plan_json::jsonb->>'ChangeCount')::integer AND history_verified AND outcome_digest ~ '^[A-F0-9]{64}$') AND (root_state <> 'Partial' OR changed_count > 0 AND completed_count < (plan_json::jsonb->>'EntryCount')::integer AND unknown_count = 0 AND history_verified AND outcome_digest ~ '^[A-F0-9]{64}$') AND (root_state <> 'Aborted' OR changed_count = 0 AND unknown_count = 0) AND (root_state <> 'Unknown' OR unknown_count > 0)) IS TRUE)");
                table.HasCheckConstraint("ck_container_recursive_ownership_receipt_binding", "receipt_json IS NULL OR ((receipt_json::jsonb->>'Id' = execution_job_id::text AND receipt_json::jsonb->>'ContainerId' = container_id AND receipt_json::jsonb->>'InstanceId' = instance_id AND receipt_json::jsonb->>'Fingerprint' = plan_json::jsonb->>'Fingerprint' AND receipt_json::jsonb->>'TargetProof' = plan_json::jsonb->>'TargetProof' AND receipt_json::jsonb->>'State' = root_state AND (receipt_json::jsonb->>'CompletedCount')::integer = completed_count AND (receipt_json::jsonb->>'ChangedCount')::integer = changed_count AND (receipt_json::jsonb->>'AbortedCount')::integer = aborted_count AND (receipt_json::jsonb->>'NotStartedCount')::integer = not_started_count AND (receipt_json::jsonb->>'UnknownCount')::integer = unknown_count AND receipt_json::jsonb->>'OutcomeDigest' = outcome_digest AND (receipt_json::jsonb->>'BindingCurrent')::boolean = binding_current AND (receipt_json::jsonb->>'HistoryAvailable')::boolean = history_available AND (receipt_json::jsonb->>'HistoryVerified')::boolean = history_verified AND (NOT (receipt_json::jsonb->>'HistoryMayExist')::boolean OR history_may_exist) AND receipt_json::jsonb->>'HistoryDigest' = COALESCE(history_digest,'')) IS TRUE)");
                table.HasCheckConstraint("ck_container_recursive_ownership_lease", "(lease_token IS NULL) = (lease_expires_at_utc IS NULL)");
                table.HasCheckConstraint("ck_container_recursive_ownership_ack", "(state = 'Acknowledged') = (acknowledged_by IS NOT NULL AND acknowledgement_json IS NOT NULL) AND (acknowledged_by IS NULL) = (acknowledgement_json IS NULL) AND (acknowledgement_json IS NULL OR receipt_json IS NOT NULL AND octet_length(acknowledgement_json) BETWEEN 1 AND 32768)");
            });
            entity.HasKey(r => r.Id);
            entity.Property(r => r.ActorSubject).HasMaxLength(256); entity.Property(r => r.AcknowledgedBy).HasMaxLength(256);
            entity.Property(r => r.TraceId).HasMaxLength(128); entity.Property(r => r.ContainerId).HasMaxLength(64); entity.Property(r => r.InstanceId).HasMaxLength(64);
            entity.Property(r => r.RelativePath).HasMaxLength(4096);
            entity.Property(r => r.CommandJson).HasColumnType("text"); entity.Property(r => r.PlanJson).HasColumnType("text"); entity.Property(r => r.AcknowledgementJson).HasColumnType("text");
            entity.Property(r => r.ReceiptJson).HasColumnType("text"); entity.Property(r => r.RootState).HasMaxLength(16);
            entity.Property(r => r.State).HasMaxLength(16); entity.Property(r => r.ResultCode).HasMaxLength(64); entity.Property(r => r.Version).IsConcurrencyToken();
            foreach (var name in new[] { nameof(ContainerRecursiveOwnershipIntent.LoginBinding), nameof(ContainerRecursiveOwnershipIntent.OwnerHash), nameof(ContainerRecursiveOwnershipIntent.RequestHash),
                nameof(ContainerRecursiveOwnershipIntent.PlanHash), nameof(ContainerRecursiveOwnershipIntent.ExecutionHash), nameof(ContainerRecursiveOwnershipIntent.OutcomeDigest), nameof(ContainerRecursiveOwnershipIntent.HistoryDigest) }) entity.Property(name).HasMaxLength(64);
            entity.HasIndex(r => new { r.ActorSubject, r.IdempotencyKey }).IsUnique();
            entity.HasIndex(r => r.ExecutionJobId).IsUnique().HasFilter("execution_job_id IS NOT NULL");
            entity.HasIndex(r => r.LeaseToken).IsUnique().HasFilter("lease_token IS NOT NULL");
            entity.HasIndex(r => new { r.ContainerId, r.CompletedAtUtc });
            entity.HasIndex(r => new { r.NextAttemptAtUtc, r.Id }).HasFilter("completed_at_utc IS NULL");
            entity.HasIndex(r => r.PublishBarrier).IsUnique().HasFilter("publish_barrier");
            entity.HasOne<OperationJob>().WithMany().HasForeignKey(r => r.Id).OnDelete(DeleteBehavior.Restrict);
            entity.HasOne<OperationJob>().WithMany().HasForeignKey(r => r.ExecutionJobId).OnDelete(DeleteBehavior.Restrict);
        });
    }
}
